import torch.nn as nn
import avelang
import avelang.language as al

BLOCK_SIZE: al.constexpr = 256


@avelang.jit
def gelu_f32(x: al.f32) -> al.f32:
    """GELU tanh approximation on a single f32 scalar."""
    x3 = x * x * x
    inner = 0.7978845608028654 * (x + 0.044715 * x3)

    if inner >= 0.0:
        exp_neg = al.exp(-2.0 * inner)
        tanh_val = (1.0 - exp_neg) / (1.0 + exp_neg)
    else:
        exp_pos = al.exp(2.0 * inner)
        tanh_val = (exp_pos - 1.0) / (exp_pos + 1.0)

    return 0.5 * x * (1.0 + tanh_val)


@avelang.jit
def gelu_kernel(
    x_ptr: al.Pointer(al.bf16),
    out_ptr: al.Pointer(al.bf16),
    n: al.i32,
):
    """Grid-stride GELU kernel."""
    block_id = al.block_id(0)
    thread_id = al.thread_id(0)

    start = block_id * BLOCK_SIZE + thread_id
    stride = al.grid_dim(0) * BLOCK_SIZE

    layout = al.make_layout((n,), (1,))
    x = al.make_tensor(x_ptr, al.bf16, layout)
    out = al.make_tensor(out_ptr, al.bf16, layout)

    for idx in al.range(start, n, stride):
